  --glass-border: rgba(255, 255, 255, 0.65);
  --glass-border-focus: rgba(255, 255, 255, 0.9);
  --glass-shadow: 
    0 4px 30px rgba(0, 0, 0, 0.02),
    0 1px 3px rgba(0, 0, 0, 0.01),
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    inset 0 -1px 2px rgba(255, 255, 255, 0.3);
  --glass-shadow-active: 
    0 12px 40px rgba(31, 38, 135, 0.06),
    0 1px 3px rgba(0, 0, 0, 0.01),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);

  /* Text colors - Premium high-contrast slate & charcoal */
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --text-tertiary: #94a3b8;
  --text-white: #ffffff;

  /* Accent colors - soft organic liquid tones */
  --accent-primary: #0f172a; /* deep charcoal / black */
  --accent-primary-hover: #334155;
  --accent-blue: #0284c7;
  --accent-blue-bg: rgba(2, 132, 199, 0.08);
  --accent-green: #10b981;
  --accent-green-bg: rgba(16, 185, 129, 0.08);
  --accent-orange: #f97316;
  --accent-orange-bg: rgba(249, 115, 22, 0.08);
  --accent-red: #ef4444;
  --accent-red-bg: rgba(239, 68, 68, 0.08);

  /* Border radius */
  --radius-xs: 8px;
  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --radius-xl: 32px;

  /* Transitions */
  --transition-smooth: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-bounce: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
