}

.logo-subtitle {
  font-family: var(--font-serif);
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: -3px;
  font-style: italic;
}

.view-selector {
  display: flex;
  background: rgba(15, 23, 42, 0.05);
  border-radius: 99px;
  padding: 4px;
