}

/* Split screen layout for desktop presentation */
.split-view-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  flex: 1;
}

/* General Layouts */
.portal-pane {
  display: flex;
  flex-direction: column;
  gap: 20px;
  overflow: hidden;
